const ASSETS = {"anotacoes.html":"<!doctype html>\n<html lang=\"pt-BR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Anotações · Mesa Pathfinder</title><link rel=\"stylesheet\" href=\"styles.css\"></head>\n<body><header class=\"topbar\"><div class=\"shell topbar-inner\"><a class=\"brand\" href=\"mesa.html\"><span class=\"brand-mark\"><span>ᚠ</span></span><span><span class=\"brand-title\">Mesa Pathfinder</span><br><span class=\"brand-sub\">campanha e inventário</span></span></a><nav><a href=\"mesa.html\">Mesa</a></nav></div></header>\n<main class=\"shell\"><section class=\"hero\"><div><div class=\"eyebrow\">Diário da campanha</div><h1>Anotações</h1><p class=\"lead\">Use esta página para registrar o que aconteceu, o que precisa ser confirmado e o que está carregando.</p><p class=\"cloud-status\" data-cloud-status>Conectando à nuvem…</p></div><div class=\"hero-actions\"><button class=\"btn primary\" data-save>Salvar na nuvem</button><button class=\"btn ghost\" data-reset>Restaurar base</button><button class=\"btn ghost\" data-export>Baixar backup</button><label class=\"btn ghost file-button\">Importar backup<input type=\"file\" data-import accept=\"application/json\"></label></div></section>\n<section class=\"grid grid-2\"><div class=\"panel\"><div class=\"panel-head\"><div><h2>Próximas dúvidas</h2><p>Levar para o Mestre ou conferir no livro.</p></div></div><textarea data-bind=\"notes.questions\"></textarea></div><div class=\"panel\"><div class=\"panel-head\"><div><h2>Resumo da última sessão</h2><p>O que aconteceu e o que mudou.</p></div></div><textarea data-bind=\"notes.session\" placeholder=\"Escreva aqui após a sessão...\"></textarea></div></section>\n<section class=\"panel section-space\"><div class=\"panel-head\"><div><h2>Inventário</h2><p>Itens transcritos da ficha; corrija nomes e quantidades quando necessário.</p></div></div><div class=\"grid grid-3\"><div class=\"field\"><label>Itens carregados</label><textarea data-bind=\"inventory.carried\"></textarea></div><div class=\"field\"><label>Consumíveis</label><textarea data-bind=\"inventory.consumables\"></textarea></div><div class=\"field\"><label>Itens equipados</label><textarea data-bind=\"inventory.equipped\"></textarea></div></div><div class=\"field section-space\"><label>Riqueza</label><input data-bind=\"inventory.wealth\"></div></section>\n<section class=\"grid grid-2 section-space\"><div class=\"panel\"><div class=\"panel-head\"><div><h2>Origem e personalidade</h2><p>Para manter o personagem consistente.</p></div></div><textarea data-bind=\"notes.personality\"></textarea><div class=\"divider\"></div><label>História</label><textarea data-bind=\"notes.history\"></textarea></div><div class=\"panel\"><div class=\"panel-head\"><div><h2>Pessoas e grupos</h2><p>Atualize durante a campanha.</p></div></div><div class=\"field\"><label>Aliados</label><textarea data-bind=\"notes.allies\"></textarea></div><div class=\"field section-space\"><label>Inimigos</label><textarea data-bind=\"notes.enemies\"></textarea></div><div class=\"field section-space\"><label>Organizações</label><textarea data-bind=\"notes.organizations\"></textarea></div></div></section>\n<div class=\"save-bar\"><button class=\"btn primary\" data-save>Salvar tudo <span data-save-status></span></button></div></main><footer class=\"shell footer\"><span>Anotações da campanha</span><span>Última abertura: <span data-now></span></span></footer><script src=\"app.js\"></script></body></html>\n","app.js":"const DEFAULTS = {\n  profile: { name: '', player: '', level: '1', xp: '0', ancestry: '', heritage: '', background: '', className: '', instinct: '', deity: '' },\n  stats: Object.fromEntries(['str','dex','con','int','wis','cha','hpMax','hpCurrent','hpTemp','ac','fort','reflex','will','perception','speed','classDc'].map(key=>[key,'0'])),\n  skills: Object.fromEntries(['acrobatics','arcana','athletics','diplomacy','deception','stealth','intimidation','thievery','crafting','medicine','nature','occultism','performance','religion','society','survival','warfareLore'].map(key=>[key,'0'])),\n  languages:'', feats: { ancestry:'',ancestryTalent:'',background:'',class1:'',class2:'',skill2:'',archetype:'' },\n  abilities:{}, attacks:[], references:[], fieldReferences:{}, extra:{},\n  inventory:{carried:'',consumables:'',equipped:'',wealth:''},\n  notes:{session:'',questions:'',allies:'',enemies:'',organizations:'',personality:'',history:''},\n  // Campos da página Sessão (docs/modelo-da-ficha.md); fichas antigas ganham os vazios no merge.\n  heroPoints:'0', conditions:[], spells:[], items:[],\n  spellcasting:{tradition:'',kind:'',attack:'',dc:'',slots:{},focus:{max:'0',current:'0'}}\n};\nconst skillInfo = {\n  acrobatics:['Acrobatismo','Equilibrar-se, Atravessar Acrobaticamente e Escapar.'],arcana:['Arcanismo','Conhecimentos arcanos, Identificar Magia e Decifrar Escrita apropriada.'],athletics:['Atletismo','Escalar, Nadar, Saltar, Agarrar, Derrubar, Desarmar, Empurrar e Reposicionar. Cada ação tem seus requisitos.'],diplomacy:['Diplomacia','Impressionar, Pedir e Obter Informação.'],deception:['Dissimulação','Mentir, Fintar, Personificar e Criar uma Distração.'],stealth:['Furtividade','Esconder-se, Esgueirar-se e Evitar Observação.'],intimidation:['Intimidação','Desmoralizar em combate e Coagir. Consulte requisitos e imunidade temporária no livro.'],thievery:['Ladroagem','Abrir Fechaduras, Desabilitar Dispositivos, Palmear e Furtar.'],crafting:['Manufatura','Criar, Reparar e identificar materiais e itens apropriados.'],medicine:['Medicina','Primeiros Socorros, Tratar Ferimentos, Doenças e Venenos.'],nature:['Natureza','Conhecimentos naturais, Comandar um Animal e ações mágicas apropriadas.'],occultism:['Ocultismo','Conhecimentos ocultos, espíritos, fenômenos e magia ocultista.'],performance:['Performance','Atuar, cantar, tocar ou realizar apresentações.'],religion:['Religião','Conhecimentos religiosos, divindades, mortos-vivos e magia divina.'],society:['Sociedade','Povos, história, leis, culturas e Subsistir em cidades.'],survival:['Sobrevivência','Rastrear, Subsistir, Orientar-se e Cobrir Rastros.'],warfareLore:['Saber de Guerra','Recordar Conhecimento sobre táticas, batalhas e exércitos.']\n};\nconst escapeAttr = value => String(value ?? '').replaceAll('&','&amp;').replaceAll('\"','&quot;').replaceAll('<','&lt;').replaceAll('>','&gt;');\nconst clone = value => JSON.parse(JSON.stringify(value));\nfunction merge(base, extra) { for(const [key,value] of Object.entries(extra || {})) { if(['__proto__','prototype','constructor'].includes(key)) continue; if(value && typeof value==='object' && !Array.isArray(value)) base[key]=merge(base[key] && typeof base[key]==='object' ? base[key] : {},value); else base[key]=value; } return base; }\nfunction getByPath(object,path) { return path.split('.').reduce((value,key)=>value?.[key],object); }\nfunction setByPath(object,path,value) { const parts=path.split('.'); if(parts.some(key=>['__proto__','prototype','constructor'].includes(key))) return; let target=object; for(const key of parts.slice(0,-1)) target=target[key] ||= {}; target[parts.at(-1)]=value; }\nlet session, character, data, books=[], pending=false, conflict=false, timer, saving=null, editCounter=0;\nconst isMesa = location.pathname.endsWith('/mesa.html');\nlet selectedId = new URLSearchParams(location.search).get('character');\nfunction localKey() { return `mesa-v4:${session.user.id}:${character.id}`; }\nfunction readOnly() { return character?.readOnly; }\nasync function request(url,method='GET',payload) {\n  const response=await fetch(url,{method,cache:'no-store',headers:payload?{'content-type':'application/json'}:undefined,body:payload?JSON.stringify(payload):undefined});\n  let result; try { result=await response.json(); } catch { result={error:'Resposta inválida do servidor.'}; }\n  if(!response.ok) { const error=new Error(result.error || 'Falha de conexão.'); error.status=response.status; throw error; }\n  return result;\n}\nfunction api(path,method,payload) { return request('/api/'+path,method,payload); }\n// Rotas do servidor da mesa (login por código); só existem quando session.invitationMode é 'access-code'.\nfunction auth(path,payload) { return request('/auth/'+path,'POST',payload || {}); }\nfunction accessCodes() { return session?.invitationMode==='access-code'; }\nfunction setStatus(message,state='') { document.querySelectorAll('[data-cloud-status]').forEach(el=>{el.textContent=message;el.dataset.state=state;}); document.querySelectorAll('[data-save-status]').forEach(el=>el.textContent=state==='saved'?' · salvo':state==='saving'?' · salvando…':''); }\nfunction backupLocal() { if(!character || readOnly()) return; try { localStorage.setItem(localKey(),JSON.stringify({data,version:character.version,pending,updatedAt:new Date().toISOString()})); } catch { setStatus('Não foi possível gravar o backup neste aparelho. Use Baixar backup.','offline'); } }\nfunction dirty() { if(readOnly()) return; pending=true;editCounter++;backupLocal();setStatus('Alterações pendentes · salvamento automático…','saving');clearTimeout(timer);timer=setTimeout(saveData,1100); }\nasync function saveData() {\n  clearTimeout(timer);\n  if(!character || readOnly()) return;\n  if(conflict) { setStatus('Conflito: baixe seu backup e recarregue antes de continuar.','offline'); return; }\n  if(saving) { await saving; if(pending) return saveData(); return; }\n  const currentEdit=editCounter;\n  const snapshot=clone(data);\n  backupLocal();setStatus('Salvando na nuvem…','saving');\n  saving=(async()=>{try { const result=await api('characters/'+character.id,'PUT',{data:snapshot,version:character.version}); character.version=result.version;pending=editCounter!==currentEdit;backupLocal();setStatus(pending?'Há novas alterações pendentes.':`Salvo na nuvem · ${new Date(result.updatedAt).toLocaleTimeString('pt-BR')}`,pending?'saving':'saved');return true; } catch(error) { if(error.status===409) conflict=true;setStatus(error.message+' · backup local preservado.','offline');return false;} })();\n  const ok=await saving;saving=null;\n  if(ok && pending) {clearTimeout(timer);timer=setTimeout(saveData,600);}return ok;\n}\nfunction exportData() { const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`personagem-${character.id}-${new Date().toISOString().slice(0,10)}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),5000); }\nfunction updateCalculations() { document.querySelectorAll('[data-calc=\"rage-temp\"]').forEach(el=>el.textContent=(Number(data.profile.level)||0)+(Number(data.stats.con)||0)); document.querySelectorAll('[data-barbarian]').forEach(el=>el.hidden=!/b[áa]rbaro/i.test(data.profile.className)); }\nfunction bindField(el) {\n  const path=el.dataset.bind || 'extra.'+el.dataset.saveKey;\n  const value=getByPath(data,path) ?? '';\n  if('value' in el) el.value=value;else el.textContent=value;\n  if(el.dataset.wired) return;el.dataset.wired='1';\n  el.addEventListener('input',()=>{setByPath(data,path,el.type==='checkbox'?el.checked:el.value);document.querySelectorAll('[data-bind]').forEach(other=>{if(other!==el && other.dataset.bind===path) {if('value' in other) other.value=el.value;else other.textContent=el.value;}});updateCalculations();dirty();});\n}\nfunction bindAll(root=document) { root.querySelectorAll('[data-bind],[data-save-key]').forEach(bindField); if(readOnly()) root.querySelectorAll('input,textarea,select,[data-mutate]').forEach(el=>el.disabled=true); }\nfunction refMarkup(path,ref={}) {\n  ref ||= {};\n  const book=books.find(book=>book.id===ref.book);\n  const valid=book && Number(ref.page)>=1 && Number(ref.page)<=book.pages;\n  return `<div class=\"reference-controls\"><label>Livro<select aria-label=\"Livro da referência\" data-bind=\"${path}.book\"><option value=\"\">Sem livro</option>${books.map(book=>`<option value=\"${book.id}\">${book.name}</option>`).join('')}</select></label><label>Pág. impressa<input type=\"number\" min=\"1\" max=\"469\" aria-label=\"Página impressa\" data-bind=\"${path}.page\"></label><a class=\"btn small ${valid?'':'disabled-link'}\" ${valid?`href=\"livro.html?book=${encodeURIComponent(ref.book)}&page=${Number(ref.page)}\" target=\"_blank\" rel=\"noopener\"`:'aria-disabled=\"true\"'}>Abrir página ↗</a></div>`;\n}\nfunction wireRefs(root) {\n  root.querySelectorAll('.reference-controls').forEach(group=>{\n    const select=group.querySelector('select'), page=group.querySelector('input'), link=group.querySelector('a');\n    const update=()=>{const book=books.find(item=>item.id===select.value),n=Number(page.value);page.max=book?.pages || 469;const valid=book&&Number.isInteger(n)&&n>=1&&n<=book.pages;link.classList.toggle('disabled-link',!valid);if(valid) {link.href=`livro.html?book=${book.id}&page=${n}`;link.target='_blank';link.rel='noopener';link.removeAttribute('aria-disabled');}else{link.removeAttribute('href');link.setAttribute('aria-disabled','true');}};\n    select.addEventListener('change',update);page.addEventListener('input',update);update();\n  });\n}\nfunction augmentFieldReferences() {\n  document.querySelectorAll('input[data-bind^=\"feats.\"]').forEach(input=>{const key=input.dataset.bind.replace('.','_');if(!data.fieldReferences[key]){const match=String(getByPath(data,input.dataset.bind)||'').match(/Livro\\s*(1|2).*?p\\.\\s*(\\d+)/i);if(match)data.fieldReferences[key]={book:'livro'+match[1],page:match[2]};}const box=document.createElement('div');box.innerHTML=refMarkup('fieldReferences.'+key,data.fieldReferences[key]);const label=input.closest('label');if(label){const wrapper=document.createElement('div');wrapper.className='field';label.replaceWith(wrapper);wrapper.append(label,box);}else input.after(box);});\n}\nfunction renderSkills() {\n  const root=document.querySelector('[data-skills]');if(!root)return;\n  root.innerHTML=Object.entries(skillInfo).map(([key,[name,description]])=>`<article class=\"skill-card\"><div class=\"skill-main\"><div><strong>${name}</strong><small>Valor total editável</small></div><input aria-label=\"Valor de ${name}\" data-bind=\"skills.${key}\"></div><button type=\"button\" class=\"info-button\" data-explain=\"${key}\">Explicar</button><details><summary>Referência no livro</summary>${refMarkup('fieldReferences.skill_'+key,data.fieldReferences['skill_'+key])}</details></article>`).join('');\n  root.querySelectorAll('[data-explain]').forEach(button=>button.addEventListener('click',()=>openHelp(...skillInfo[button.dataset.explain])));\n}\nfunction renderAbilities() {\n  const root=document.querySelector('[data-abilities]');if(!root)return;\n  root.innerHTML=Object.entries(data.abilities).map(([key,item])=>`<article class=\"ability-card\"><div class=\"ability-title\"><input aria-label=\"Nome da habilidade\" data-bind=\"abilities.${key}.name\"><button class=\"info-button\" data-remove-ability=\"${key}\" data-mutate>Remover</button></div><label>Descrição / efeito<textarea data-bind=\"abilities.${key}.effect\"></textarea></label><label>Fonte / observação<input data-bind=\"abilities.${key}.source\"></label>${refMarkup('abilities.'+key+'.reference',item.reference)}</article>`).join('');\n  root.querySelectorAll('[data-remove-ability]').forEach(button=>button.addEventListener('click',()=>{if(confirm('Remover esta habilidade?')){delete data.abilities[button.dataset.removeAbility];dirty();renderDynamic();}}));\n}\nfunction renderAttacks() {\n  const root=document.querySelector('[data-attacks]');if(!root)return;\n  root.innerHTML=data.attacks.map((item,i)=>`<article class=\"attack-card\"><div class=\"form-grid\">${[['name','Arma / ataque'],['bonus','Bônus'],['damage','Dano'],['traits','Traços'],['notes','Observações']].map(([key,label])=>`<label class=\"field\">${label}<input data-bind=\"attacks.${i}.${key}\"></label>`).join('')}</div>${refMarkup('attacks.'+i+'.reference',item.reference)}<button class=\"info-button\" data-remove-attack=\"${i}\" data-mutate>Remover arma</button></article>`).join('');\n  root.querySelectorAll('[data-remove-attack]').forEach(button=>button.addEventListener('click',()=>{if(confirm('Remover esta arma?')){data.attacks.splice(Number(button.dataset.removeAttack),1);dirty();renderDynamic();}}));\n}\nfunction renderReferences() {\n  const root=document.querySelector('[data-references]');if(!root)return;\n  root.innerHTML=data.references.map((ref,i)=>`<article class=\"ability-card\"><div class=\"form-grid\"><label>Título<input data-bind=\"references.${i}.title\"></label><label>Categoria<input data-bind=\"references.${i}.category\" placeholder=\"classe, talento, ação…\"></label></div><label>Notas<textarea data-bind=\"references.${i}.notes\"></textarea></label>${refMarkup('references.'+i,ref)}<button class=\"info-button\" data-remove-ref=\"${i}\" data-mutate>Remover referência</button></article>`).join('');\n  root.querySelectorAll('[data-remove-ref]').forEach(button=>button.addEventListener('click',()=>{data.references.splice(Number(button.dataset.removeRef),1);dirty();renderDynamic();}));\n}\nfunction renderDynamic() {renderSkills();renderAbilities();renderAttacks();renderReferences();bindAll();wireRefs(document);}\nfunction openHelp(title,description) {const dialog=document.querySelector('#help-modal');if(!dialog){alert(title+'\\n\\n'+description);return;}dialog.querySelector('[data-help-title]').textContent=title;dialog.querySelector('[data-help-body]').textContent=description;dialog.showModal();}\nfunction addControls() {\n  for(const [selector,text,callback] of [['[data-abilities]','+ Adicionar habilidade',()=>{data.abilities['a_'+crypto.randomUUID().replaceAll('-','')]={name:'Nova habilidade',effect:'',source:'',reference:{}};}],['[data-attacks]','+ Adicionar arma',()=>data.attacks.push({name:'',bonus:'',damage:'',traits:'',notes:'',reference:{}})],['[data-references]','+ Adicionar referência',()=>data.references.push({title:'',category:'',notes:'',book:'',page:''})]]) {\n    const root=document.querySelector(selector);if(!root)continue;const button=document.createElement('button');button.className='btn section-space';button.textContent=text;button.dataset.mutate='1';button.disabled=readOnly();button.addEventListener('click',()=>{callback();dirty();renderDynamic();});root.after(button);\n  }\n}\nfunction migrateReferences() {\n  for(const item of Object.values(data.abilities)) {if(item.reference)continue;const match=item.source?.match(/Livro\\s*(1|2).*?p\\.\\s*(\\d+)/i);if(match)item.reference={book:'livro'+match[1],page:match[2]};}\n}\nasync function initCharacter() {\n  const records=(await api('characters')).characters;\n  if(!selectedId) selectedId=records.find(item=>item.owned)?.id;\n  if(!selectedId) {location.replace('mesa.html');return;}\n  character=await api('characters/'+encodeURIComponent(selectedId));\n  data=merge(clone(DEFAULTS),character.data);migrateReferences();\n  // Nunca misturar dados de contas/personagens nem substituir nuvem automaticamente.\n  const draft=localStorage.getItem(localKey());\n  if(draft && !readOnly()) {try {const parsed=JSON.parse(draft);if(parsed.pending && confirm('Há alterações locais não enviadas desta ficha. Restaurar para revisar?')) {data=merge(clone(DEFAULTS),parsed.data);pending=true;conflict=parsed.version!==character.version;}}catch{}}\n  document.title=(data.profile.name || 'Personagem')+' · Mesa Pathfinder';\n  document.querySelectorAll('nav').forEach(nav=>{nav.innerHTML=`<a href=\"mesa.html\">Mesa</a><a href=\"sessao.html?character=${encodeURIComponent(selectedId)}\">Sessão</a><a href=\"index.html?character=${encodeURIComponent(selectedId)}\">Ficha</a><a href=\"progressao.html?character=${encodeURIComponent(selectedId)}\">Progressão</a><a href=\"anotacoes.html?character=${encodeURIComponent(selectedId)}\">Anotações</a><a href=\"busca.html\">Buscar regras</a>`;});\n  augmentFieldReferences();renderDynamic();addControls();updateCalculations();\n  document.querySelectorAll('[data-save]').forEach(button=>{button.disabled=readOnly();button.addEventListener('click',saveData);});\n  document.querySelectorAll('[data-reset]').forEach(button=>{button.hidden=true;});\n  document.querySelectorAll('[data-export]').forEach(button=>button.addEventListener('click',exportData));\n  document.querySelectorAll('[data-import]').forEach(input=>input.addEventListener('change',async()=>{if(readOnly())return;try {const parsed=JSON.parse(await input.files[0].text());if(!parsed.profile || typeof parsed.profile.name!=='string')throw new Error('Backup inválido.');if(!confirm('Substituir os campos desta ficha pelo backup?'))return;data=merge(clone(DEFAULTS),parsed);dirty();if(await saveData())location.reload();}catch(error){alert(error.message);}input.value='';}));\n  document.querySelectorAll('[data-help]').forEach(button=>button.addEventListener('click',()=>openHelp(...skillInfo[button.dataset.help])));\n  document.querySelectorAll('[data-now]').forEach(el=>el.textContent=new Date().toLocaleDateString('pt-BR'));\n  setStatus(readOnly()?'Visão do mestre · somente leitura':pending?'Backup local restaurado · revise e salve':'Ficha carregada da nuvem · salvamento automático',readOnly()?'':'saved');\n  document.addEventListener('input',event=>{if(event.target.matches('[data-bind],[data-save-key]'))backupLocal();});\n  document.querySelectorAll('nav a').forEach(link=>link.addEventListener('click',async event=>{if(!pending)return;event.preventDefault();const ok=await saveData();if(ok || confirm('Ainda há alterações não salvas na nuvem. Sair mesmo assim?'))location.href=link.href;}));\n  window.addEventListener('beforeunload',event=>{if(pending){backupLocal();event.preventDefault();event.returnValue='';}});\n  document.addEventListener('visibilitychange',()=>{if(document.hidden && pending && !conflict)saveData();});\n  window.addEventListener('online',()=>{if(pending&&!conflict)saveData();});\n  document.dispatchEvent(new CustomEvent('mesa:ficha'));\n}\nasync function createCharacter(form) {\n  const values=new FormData(form),next=clone(DEFAULTS);\n  next.profile.name=String(values.get('name')).trim();next.profile.player=String(values.get('player')||'');next.profile.className=String(values.get('className')||'');next.profile.ancestry=String(values.get('ancestry')||'');\n  const result=await api('characters','POST',{data:next});location.href='index.html?character='+encodeURIComponent(result.id);\n}\nasync function refreshMembers() {\n  const root=document.querySelector('[data-members]');if(!root || !session.user.admin)return;\n  const result=await api('members');\n  root.innerHTML=result.members.map(member=>`<article class=\"member-row\"><div><strong>${escapeAttr(member.email)}</strong><small>${member.active?(member.accepted?'Entrou na mesa':accessCodes()?'Cadastrado · ainda não entrou':'Cadastrado · acesso privado do Site necessário'):'Acesso revogado'}</small>${accessCodes()&&member.active&&member.email!==session.user.email?`<button type=\"button\" class=\"info-button section-space\" data-new-code=\"${escapeAttr(member.email)}\">Novo link de acesso</button>`:''}</div><select aria-label=\"Papel de ${escapeAttr(member.email)}\" data-role-email=\"${escapeAttr(member.email)}\"><option value=\"player\" ${member.role==='player'?'selected':''}>Jogador</option><option value=\"master\" ${member.role==='master'?'selected':''}>Mestre</option></select><button class=\"btn\" data-revoke=\"${escapeAttr(member.email)}\" ${member.email===session.user.email?'disabled':''}>Revogar</button></article>`).join('');\n  root.querySelectorAll('[data-role-email]').forEach(select=>select.addEventListener('change',async()=>{if(!confirm(`Alterar o papel de ${select.dataset.roleEmail} para ${select.value==='master'?'mestre (verá todas as fichas)':'jogador'}?`)){await refreshMembers();return;}try{await api('members','POST',{email:select.dataset.roleEmail,role:select.value});location.reload();}catch(error){alert(error.message);}}));\n  root.querySelectorAll('[data-revoke]').forEach(button=>button.addEventListener('click',async()=>{if(!confirm('Revogar o acesso à mesa? As fichas serão mantidas.'))return;try{await api('members','DELETE',{email:button.dataset.revoke});await refreshMembers();}catch(error){alert(error.message);}}));\n  root.querySelectorAll('[data-new-code]').forEach(button=>button.addEventListener('click',async()=>{if(!confirm(`Gerar um novo link de acesso para ${button.dataset.newCode}? O link antigo e os aparelhos conectados deixam de funcionar.`))return;try{await showAccess(button.dataset.newCode);document.querySelector('[data-invite-result]').scrollIntoView({block:'center'});}catch(error){alert(error.message);}}));\n}\nasync function showAccess(email) {\n  const access=await auth('code',{email});\n  document.querySelector('[data-invite-result]').textContent=`Link de acesso de ${access.email} pronto. Mande só para essa pessoa: ele entra direto e vale como senha (código ${access.code}).`;\n  document.querySelector('[data-invite-link]').value=access.link;\n}\nasync function initMesa() {\n  document.querySelector('[data-account]').textContent=session.user.email;\n  document.querySelector('[data-role]').textContent=(session.user.role==='master'?'Mestre':'Jogador')+(session.user.admin?' · administrador':'');\n  const result=await api('characters'),root=document.querySelector('[data-characters]');\n  document.querySelector('[data-list-title]').textContent=session.user.role==='master'?'Todos os personagens':'Meus personagens';\n  root.innerHTML=result.characters.length?result.characters.map(item=>`<a class=\"character-card\" href=\"sessao.html?character=${encodeURIComponent(item.id)}\"><div class=\"eyebrow\">${item.owned?'Seu personagem':'Visão do mestre · leitura'}</div><h3>${escapeAttr(item.name || 'Sem nome')}</h3><p>${escapeAttr(item.ancestry)} · ${escapeAttr(item.className || 'Classe a definir')} · Nível ${escapeAttr(item.level)}</p><small>${escapeAttr(item.ownerEmail)}</small><span class=\"card-arrow\">Abrir ficha ↗</span></a>`).join(''):'<div class=\"note\">Você ainda não criou um personagem. Comece pelo formulário abaixo.</div>';\n  document.querySelector('[data-create]').addEventListener('submit',async event=>{event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;try{await createCharacter(event.target);}catch(error){alert(error.message);button.disabled=false;}});\n  const admin=document.querySelector('[data-admin]');admin.hidden=!session.user.admin;\n  document.querySelectorAll('[data-master-only]').forEach(el=>el.hidden=session.user.role!=='master');\n  const logout=document.querySelector('[data-logout]');logout.hidden=!accessCodes();logout.addEventListener('click',async()=>{try{await auth('logout');}finally{location.href='/entrar.html';}});\n  if(session.user.admin){\n    document.querySelector('[data-invite-link]').value=new URL('/mesa.html',location.href).href;\n    if(accessCodes())document.querySelector('[data-invite-help]').innerHTML='1. Cadastre o e-mail e o papel abaixo.<br>2. Copie o link de acesso que aparece e mande só para essa pessoa: ele entra direto e vale como senha.<br>3. Perdeu o link? Gere um novo na lista abaixo; os aparelhos antigos saem da conta.';\n    await refreshMembers();\n    document.querySelector('[data-invite]').addEventListener('submit',async event=>{event.preventDefault();const form=new FormData(event.target);try{const result=await api('members','POST',{email:form.get('email'),role:form.get('role')});if(accessCodes())await showAccess(result.email);else{document.querySelector('[data-invite-result]').textContent=`${result.email} cadastrado. Agora libere esse e-mail em Compartilhar no Site e envie o link abaixo. Este cadastro não envia e-mail automaticamente.`;document.querySelector('[data-invite-link]').value=result.link;}await refreshMembers();event.target.reset();}catch(error){alert(error.message);}});\n  }\n  document.querySelector('[data-copy-link]').addEventListener('click',async()=>{const input=document.querySelector('[data-invite-link]');try{await navigator.clipboard.writeText(input.value);document.querySelector('[data-invite-result]').textContent=accessCodes()?'Link copiado. Mande só para a pessoa convidada.':'Link copiado. O convidado precisa entrar com o e-mail cadastrado e ter acesso privado ao Site.';}catch{input.select();}});\n  const old=localStorage.getItem('ficha-anao-barbaro-v2')||localStorage.getItem('ficha-anao-barbaro-local-backup');\n  const recover=document.querySelector('[data-recover-old]');recover.hidden=!(old&&session.user.admin);recover.addEventListener('click',async()=>{try{const oldData=JSON.parse(old);if(!confirm('Criar uma cópia separada da ficha antiga deste navegador? Nenhum personagem existente será substituído.'))return;for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(key?.startsWith('ficha-anao-barbaro-field-')){oldData.extra ||= {};oldData.extra[key.replace('ficha-anao-barbaro-field-','')]=localStorage.getItem(key);}}const result=await api('characters','POST',{data:oldData});location.href='index.html?character='+result.id;}catch(error){alert(error.message);}});\n}\nasync function init() {\n  document.querySelectorAll('main input,main textarea,main select,main button').forEach(el=>el.disabled=true);\n  try {session=await api('session');books=session.books;document.querySelectorAll('main input,main textarea,main select,main button').forEach(el=>el.disabled=false);if(isMesa)await initMesa();else await initCharacter();}\n  catch(error){const main=document.querySelector('main');main.replaceChildren();const section=document.createElement('section');section.className='panel';const title=document.createElement('h1');title.textContent='Acesso à mesa';const message=document.createElement('p');message.textContent=error.message;const login=document.createElement('a');login.className='btn primary';login.href='/signin-with-chatgpt?return_to='+encodeURIComponent(location.pathname+location.search);login.target='_top';login.textContent='Entrar';section.append(title,message,login);main.append(section);}\n}\n// Ponte para os scripts das páginas novas (sessao.js): mesma ficha, salvamento automático, backup local e conflito.\nwindow.Mesa={get session(){return session;},get character(){return character;},get data(){return data;},get books(){return books;},api,dirty,saveData,bindAll,readOnly,escapeAttr,openHelp,skillInfo};\ndocument.addEventListener('DOMContentLoaded',init);\n// Ctrl+K abre a busca de regras a partir de qualquer página da ficha/mesa.\ndocument.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();const selection=String(window.getSelection()||'').trim();location.href='busca.html'+(selection?'?q='+encodeURIComponent(selection):'');}});\n","busca.html":"<!doctype html><html lang=\"pt-BR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Buscar regras · Mesa Pathfinder</title><link rel=\"stylesheet\" href=\"styles.css\"></head><body>\n<header class=\"topbar\"><div class=\"shell topbar-inner\"><a class=\"brand\" href=\"mesa.html\"><span class=\"brand-mark\"><span>ᚠ</span></span><span><span class=\"brand-title\">Mesa Pathfinder</span><br><span class=\"brand-sub\">consulta rápida de regras</span></span></a><nav><a href=\"mesa.html\">Mesa</a><a href=\"livro.html\">Livros</a><a class=\"active\" href=\"busca.html\">Buscar</a></nav></div></header>\n<main class=\"shell\">\n<section class=\"hero\"><div><div class=\"eyebrow\">Livros abertos</div><h1 class=\"book-title\">Buscar regras</h1><p class=\"lead\">Magias, talentos, classes, ancestralidades e condições extraídas dos dois livros — clique em um resultado para ver a regra completa e abrir a página impressa.</p></div></section>\n<section class=\"panel\"><form class=\"search-box\" id=\"search-form\"><input id=\"q\" type=\"search\" placeholder=\"Ex.: bola de fogo, investida, condição cegado…\" autocomplete=\"off\" aria-label=\"Buscar regras\"><button class=\"btn primary\">Buscar</button></form>\n<div class=\"search-filters\">\n<label>Tipo<select id=\"type\" aria-label=\"Filtrar por tipo\"><option value=\"\">Tudo</option><option value=\"spell\">Magias e truques</option><option value=\"focus\">Magias de foco</option><option value=\"ritual\">Rituais</option><option value=\"feat\">Talentos</option><option value=\"class\">Classes</option><option value=\"ancestry\">Ancestralidades</option><option value=\"condition\">Condições</option></select></label>\n<label>Nível<select id=\"level\" aria-label=\"Filtrar por nível\"><option value=\"\">Qualquer</option></select></label>\n<label>Livro<select id=\"book\" aria-label=\"Filtrar por livro\"><option value=\"\">Ambos</option><option value=\"livro1\">Livro do Jogador 1</option><option value=\"livro2\">Livro do Jogador 2</option></select></label>\n<label>Traço / categoria<input id=\"trait\" placeholder=\"ex.: bárbaro, fogo, perícia\" aria-label=\"Filtrar por traço\"></label>\n</div>\n<div class=\"chips\" id=\"stats\"></div>\n<p id=\"search-status\" class=\"small muted\" role=\"status\">Digite para buscar, ou escolha um filtro para navegar.</p></section>\n<div class=\"search-layout\"><div id=\"results\"></div><aside id=\"detail\" class=\"panel detail-panel\" hidden></aside></div>\n</main>\n<footer class=\"shell footer\"><span>Conteúdo extraído dos livros · uso pessoal da mesa</span><span>Atalho: Ctrl+K abre a busca de qualquer página</span></footer>\n<script src=\"regras.js\"></script><script src=\"busca.js\"></script></body></html>\n","busca.js":"// Busca SRD: consulta às regras estruturadas extraídas dos livros. Rótulos e detalhe vêm de regras.js.\nconst { TYPE_LABELS, BOOK_NAMES, escapeHtml, markify, metaLine } = window.Regras;\nconst fields = ['q', 'type', 'level', 'book', 'trait'].map(id => document.getElementById(id));\nconst [input, typeInput, levelInput, bookInput, traitInput] = fields;\nconst results = document.getElementById('results');\nconst detail = document.getElementById('detail');\nconst status = document.getElementById('search-status');\nconst statsBox = document.getElementById('stats');\nlet currentEntry = null;\n\nfor (let level = 1; level <= 20; level++) {\n  const option = document.createElement('option');\n  option.value = String(level);\n  option.textContent = String(level);\n  levelInput.append(option);\n}\n\nasync function api(path) {\n  const response = await fetch('/api/' + path, { cache: 'no-store' });\n  const result = await response.json();\n  if (!response.ok) throw new Error(result.error || 'Falha na busca.');\n  return result;\n}\n\nfunction state() {\n  const params = new URLSearchParams();\n  for (const [key, el] of [['q', input], ['type', typeInput], ['level', levelInput], ['book', bookInput], ['trait', traitInput]]) {\n    if (el.value.trim()) params.set(key, el.value.trim());\n  }\n  return params;\n}\n\nfunction entryCard(entry) {\n  const traits = (entry.traits || '').split(',').map(t => t.trim()).filter(Boolean).slice(0, 6);\n  const card = document.createElement('article');\n  card.className = 'result-card' + (currentEntry && currentEntry === entry.id ? ' selected' : '');\n  card.innerHTML = `<h3>${markify(entry.name)}</h3><p class=\"small muted\">${escapeHtml(metaLine(entry))}</p>` +\n    (traits.length ? `<div class=\"chips\">${traits.map(t => `<span class=\"chip\">${escapeHtml(t)}</span>`).join('')}</div>` : '') +\n    (entry.snippet ? `<p class=\"result-snippet small\">${markify(entry.snippet)}</p>` : '');\n  card.addEventListener('click', () => openDetail(entry));\n  return card;\n}\n\nfunction pageCard(page) {\n  const card = document.createElement('a');\n  card.className = 'result-card page-result';\n  card.href = `livro.html?book=${encodeURIComponent(page.book)}&page=${page.page}`;\n  card.target = '_blank';\n  card.rel = 'noopener';\n  card.innerHTML = `<h3>Página — ${BOOK_NAMES[page.book] || page.book}, p. ${page.page}</h3><p class=\"small muted\">${escapeHtml(page.chapter || '')}</p>` +\n    (page.snippet ? `<p class=\"result-snippet small\">${markify(page.snippet)}</p>` : '');\n  return card;\n}\n\nasync function openDetail(entry) {\n  currentEntry = entry.id;\n  try {\n    const full = await api('entries/' + encodeURIComponent(entry.id));\n    detail.innerHTML = window.Regras.detailHtml(full, { actions: '<button class=\"btn ghost\" id=\"detail-close\" type=\"button\">Fechar</button>' });\n    detail.hidden = false;\n    detail.querySelector('#detail-close').addEventListener('click', () => { detail.hidden = true; currentEntry = null; render(currentCache); });\n    detail.scrollIntoView({ behavior: 'smooth', block: 'nearest' });\n  } catch (error) { status.textContent = error.message; }\n}\n\nlet currentCache = { entries: [], pages: [] };\nfunction render(data) {\n  currentCache = data;\n  results.replaceChildren();\n  if (data.entries.length) {\n    const head = document.createElement('h2');\n    head.textContent = 'Regras encontradas';\n    results.append(head);\n    for (const entry of data.entries) results.append(entryCard(entry));\n  }\n  if (data.pages?.length) {\n    const head = document.createElement('h2');\n    head.className = 'section-space';\n    head.textContent = 'Páginas dos livros';\n    results.append(head);\n    for (const page of data.pages) results.append(pageCard(page));\n  }\n  if (!data.entries.length && !data.pages?.length) {\n    const empty = document.createElement('div');\n    empty.className = 'note';\n    empty.textContent = data.hint || 'Nada encontrado. Tente termos menores ou sem acento, ou mude os filtros.';\n    results.append(empty);\n  }\n}\n\nlet timer = null, seq = 0;\nasync function run(quiet) {\n  const params = state();\n  const id = ++seq;\n  history.replaceState(null, '', 'busca.html' + (params.toString() ? '?' + params : ''));\n  if (!quiet) status.textContent = 'Buscando…';\n  try {\n    const data = await api('search?' + params.toString() + '&limit=40');\n    if (id !== seq) return;\n    const total = data.entries.length + (data.pages?.length || 0);\n    status.textContent = params.get('q') ? `${total} resultado(s) para “${params.get('q')}”.` : `${total} entrada(s) nos filtros atuais.`;\n    render(data);\n  } catch (error) {\n    if (id === seq) status.textContent = error.message;\n  }\n}\n\nfunction debounced() { clearTimeout(timer); timer = setTimeout(() => run(), 220); }\n\ndocument.getElementById('search-form').addEventListener('submit', event => { event.preventDefault(); run(); });\ninput.addEventListener('input', debounced);\ntraitInput.addEventListener('input', debounced);\nfor (const el of [typeInput, levelInput, bookInput]) el.addEventListener('change', () => run());\n\n(async () => {\n  const params = new URLSearchParams(location.search);\n  for (const [key, el] of [['q', input], ['type', typeInput], ['level', levelInput], ['book', bookInput], ['trait', traitInput]]) {\n    if (params.get(key)) el.value = params.get(key);\n  }\n  input.focus();\n  input.select();\n  try {\n    const stats = await api('srd/stats');\n    statsBox.innerHTML = stats.types.map(row =>\n      `<button type=\"button\" class=\"chip\" data-type=\"${row.type}\"><strong>${row.count}</strong> ${TYPE_LABELS[row.type] || row.type}</button>`).join('') +\n      `<span class=\"chip\"><strong>${stats.total}</strong> entradas</span>`;\n    statsBox.querySelectorAll('[data-type]').forEach(chip => chip.addEventListener('click', () => {\n      typeInput.value = typeInput.value === chip.dataset.type ? '' : chip.dataset.type;\n      run();\n    }));\n  } catch { /* stats são decorativos */ }\n  if (params.toString()) run(); else run(true);\n})();\n","index.html":"<!doctype html>\n<html lang=\"pt-BR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Personagem · Mesa Pathfinder</title><link rel=\"stylesheet\" href=\"styles.css\"></head>\n<body><header class=\"topbar\"><div class=\"shell topbar-inner\"><a class=\"brand\" href=\"mesa.html\"><span class=\"brand-mark\"><span>ᚠ</span></span><span><span class=\"brand-title\">Mesa Pathfinder</span><br><span class=\"brand-sub\">cada herói, sua história</span></span></a><nav><a href=\"mesa.html\">Mesa</a></nav></div></header>\n<main class=\"shell\"><section class=\"hero\"><div><div class=\"eyebrow\">Ficha do personagem</div><h1><input class=\"hero-name\" data-bind=\"profile.name\" aria-label=\"Nome do personagem\" placeholder=\"Nome do personagem\"></h1><p class=\"cloud-status\" data-cloud-status>Carregando sua ficha com segurança…</p></div><div class=\"hero-actions\"><button class=\"btn primary\" data-save>Salvar agora</button><button class=\"btn\" data-export>Baixar backup</button><label class=\"btn file-button\" data-mutate>Importar backup<input type=\"file\" data-import accept=\"application/json\"></label></div></section>\n<section class=\"grid grid-4\"><label class=\"stat\"><span class=\"stat-label\">PV atuais</span><input data-bind=\"stats.hpCurrent\" inputmode=\"numeric\" aria-label=\"PV atuais\"></label><label class=\"stat\"><span class=\"stat-label\">PV máximos</span><input data-bind=\"stats.hpMax\" inputmode=\"numeric\" aria-label=\"PV máximos\"></label><label class=\"stat\"><span class=\"stat-label\">PV temporários</span><input data-bind=\"stats.hpTemp\" inputmode=\"numeric\" aria-label=\"PV temporários\"></label><label class=\"stat\"><span class=\"stat-label\">Classe de armadura</span><input data-bind=\"stats.ac\" inputmode=\"numeric\" aria-label=\"Classe de armadura\"></label></section>\n<section class=\"panel section-space\"><div class=\"panel-head\"><div><h2>Identidade</h2><p>Qualquer classe e ancestralidade. Preencha com as regras da sua mesa.</p></div></div><div class=\"form-grid\"><label class=\"field\">Nome do jogador<input data-bind=\"profile.player\"></label><label class=\"field\">Classe<input data-bind=\"profile.className\"></label><label class=\"field\">Ancestralidade<input data-bind=\"profile.ancestry\"></label><label class=\"field\">Herança<input data-bind=\"profile.heritage\"></label><label class=\"field\">Biografia<input data-bind=\"profile.background\"></label><label class=\"field\">Instinto / subclasse<input data-bind=\"profile.instinct\"></label><label class=\"field\">Divindade<input data-bind=\"profile.deity\"></label><label class=\"field\">Nível<input data-bind=\"profile.level\" inputmode=\"numeric\"></label><label class=\"field\">Experiência<input data-bind=\"profile.xp\"></label><label class=\"field\">Idiomas<textarea data-bind=\"languages\"></textarea></label></div></section>\n<section class=\"panel section-space\"><div class=\"panel-head\"><div><h2>Atributos e defesas</h2><p>Valores manuais: não alteramos seus bônus automaticamente.</p></div></div><div class=\"grid grid-4\"><label class=\"stat\">Força<input data-bind=\"stats.str\" inputmode=\"numeric\"></label><label class=\"stat\">Destreza<input data-bind=\"stats.dex\" inputmode=\"numeric\"></label><label class=\"stat\">Constituição<input data-bind=\"stats.con\" inputmode=\"numeric\"></label><label class=\"stat\">Inteligência<input data-bind=\"stats.int\" inputmode=\"numeric\"></label><label class=\"stat\">Sabedoria<input data-bind=\"stats.wis\" inputmode=\"numeric\"></label><label class=\"stat\">Carisma<input data-bind=\"stats.cha\" inputmode=\"numeric\"></label><label class=\"stat\">Fortitude<input data-bind=\"stats.fort\" inputmode=\"numeric\"></label><label class=\"stat\">Reflexos<input data-bind=\"stats.reflex\" inputmode=\"numeric\"></label><label class=\"stat\">Vontade<input data-bind=\"stats.will\" inputmode=\"numeric\"></label><label class=\"stat\">Percepção<input data-bind=\"stats.perception\" inputmode=\"numeric\"></label><label class=\"stat\">Velocidade (m)<input data-bind=\"stats.speed\" inputmode=\"decimal\"></label><label class=\"stat\">CD de classe<input data-bind=\"stats.classDc\" inputmode=\"numeric\"></label></div><p class=\"note section-space\" data-barbarian hidden>Fúria: nível + Constituição = <strong data-calc=\"rage-temp\"></strong> PV temporários. Consulte sua versão da regra.</p></section>\n<section class=\"panel section-space\"><div class=\"panel-head\"><div><h2>Perícias</h2><p>Toque em Explicar. Cada perícia pode ter uma referência ao livro.</p></div></div><div class=\"skill-list\" data-skills></div></section>\n<section class=\"panel section-space\"><div class=\"panel-head\"><div><h2>Armas e ataques</h2><p>Adicione quantas armas precisar, com bônus, dano, traços e página.</p></div></div><div class=\"grid\" data-attacks></div></section>\n<section class=\"panel section-space\"><div class=\"panel-head\"><div><h2>Habilidades, ações e talentos</h2><p>Descrição, fonte, livro e página impressa — tudo editável.</p></div></div><div class=\"grid\" data-abilities></div></section>\n<section class=\"panel section-space\"><div class=\"panel-head\"><div><h2>Caderno de referências</h2><p>Vincule qualquer regra, magia, equipamento ou característica a uma página.</p></div></div><div class=\"grid\" data-references></div></section>\n<div class=\"save-bar\"><button class=\"btn primary\" data-save>Salvar alterações <span data-save-status></span></button></div></main>\n<dialog id=\"help-modal\"><h2 data-help-title></h2><p data-help-body></p><form method=\"dialog\"><button class=\"btn primary\">Fechar</button></form></dialog><footer class=\"shell footer\"><span>Salvamento na nuvem · backup por personagem</span><span>Se houver conflito entre dispositivos, sua edição não substitui a outra.</span></footer><script src=\"app.js\"></script></body></html>\n","livro.html":"<!doctype html><html lang=\"pt-BR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Consultar livro · Mesa Pathfinder</title><link rel=\"stylesheet\" href=\"styles.css\"></head><body><header class=\"topbar\"><div class=\"shell topbar-inner\"><a class=\"brand\" href=\"mesa.html\"><span class=\"brand-title\">Mesa Pathfinder</span></a><nav><a href=\"mesa.html\">Mesa</a><a class=\"active\" href=\"livro.html\">Livros</a><a href=\"busca.html\">Buscar regras</a></nav><a class=\"btn\" href=\"mesa.html\">Voltar à mesa</a></div></header><main class=\"shell book-shell\"><section class=\"panel\"><div class=\"eyebrow\">Livro aberto</div><h1 class=\"book-title\">Consulta de regras</h1><form class=\"book-toolbar\" id=\"page-form\"><label>Livro<select id=\"book\" aria-label=\"Livro\"></select></label><label>Página impressa<input id=\"page\" type=\"number\" min=\"1\" value=\"1\" required aria-label=\"Página impressa\"></label><button class=\"btn primary\">Abrir</button><button class=\"btn\" id=\"prev\" type=\"button\">← Anterior</button><button class=\"btn\" id=\"next\" type=\"button\">Próxima →</button><button class=\"btn\" id=\"zoom\" type=\"button\">Ampliar</button></form><p id=\"book-status\" class=\"small muted\" role=\"status\">Verificando acesso…</p></section><div class=\"book-image-wrap\" id=\"book-wrap\"><img id=\"book-image\" alt=\"Página do livro\" hidden></div></main><script src=\"livro.js\"></script><script>document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();const selection=String(window.getSelection()||'').trim();location.href='busca.html'+(selection?'?q='+encodeURIComponent(selection):'');}});</script></body></html>\n","livro.js":"let catalog=[];\nconst select=document.getElementById('book'), pageInput=document.getElementById('page'), image=document.getElementById('book-image'), status=document.getElementById('book-status');\nfunction openPage(push=true) {\n  const book=catalog.find(item=>item.id===select.value),page=Number(pageInput.value);\n  if(!book || !Number.isInteger(page) || page<1 || page>book.pages){status.textContent='Escolha uma página entre 1 e '+(book?.pages || 1)+'.';return;}\n  pageInput.max=book.pages;document.title=book.name+' · página '+page;status.textContent='Carregando '+book.name+', página impressa '+page+' (posição '+(page+book.pdfOffset)+' do PDF)…';image.hidden=true;image.src=`/api/books/${book.id}/pages/${page}`;image.alt=book.name+', página impressa '+page;document.getElementById('prev').disabled=page<=1;document.getElementById('next').disabled=page>=book.pages;\n  if(push)history.replaceState(null,'',`livro.html?book=${book.id}&page=${page}`);\n}\nimage.onload=()=>{image.hidden=false;status.textContent='Página impressa '+pageInput.value+' · use Ampliar ou o zoom do aparelho para ler.';};image.onerror=()=>{status.textContent='Não foi possível carregar esta página. Recarregue; se persistir, informe o livro e a página ao administrador.';};\ndocument.getElementById('page-form').addEventListener('submit',event=>{event.preventDefault();openPage();});document.getElementById('prev').addEventListener('click',()=>{pageInput.value=Number(pageInput.value)-1;openPage();});document.getElementById('next').addEventListener('click',()=>{pageInput.value=Number(pageInput.value)+1;openPage();});select.addEventListener('change',()=>{pageInput.value=Math.min(Number(pageInput.value),catalog.find(item=>item.id===select.value).pages);openPage();});document.getElementById('zoom').addEventListener('click',()=>{document.getElementById('book-wrap').classList.toggle('zoomed');document.getElementById('zoom').textContent=document.getElementById('book-wrap').classList.contains('zoomed')?'Ajustar à tela':'Ampliar';});\n(async()=>{try{const response=await fetch('/api/books',{cache:'no-store'}),result=await response.json();if(!response.ok)throw new Error(result.error);catalog=result.books;select.innerHTML=catalog.map(book=>`<option value=\"${book.id}\">${book.name}</option>`).join('');const query=new URLSearchParams(location.search);select.value=catalog.some(item=>item.id===query.get('book'))?query.get('book'):'livro1';pageInput.value=query.get('page')||1;openPage();}catch(error){status.textContent=error.message+' Entre na mesa para consultar os livros.';}})();\n","mesa.html":"<!doctype html><html lang=\"pt-BR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Mesa Pathfinder · Personagens e jogadores</title><link rel=\"stylesheet\" href=\"styles.css\"></head><body>\n<header class=\"topbar\"><div class=\"shell topbar-inner\"><a class=\"brand\" href=\"mesa.html\"><span class=\"brand-mark\"><span>ᚠ</span></span><span><span class=\"brand-title\">Mesa Pathfinder</span><br><span class=\"brand-sub\">aventuras compartilhadas, fichas pessoais</span></span></a><nav><a class=\"active\" href=\"mesa.html\">Personagens</a><a href=\"grupo.html\" data-master-only hidden>Grupo</a><a href=\"livro.html\">Livros</a><a href=\"busca.html\">Buscar regras</a></nav></div></header>\n<main class=\"shell\"><section class=\"hero\"><div><div class=\"eyebrow\">Sua mesa, seus heróis</div><h1>O próximo capítulo.</h1><p class=\"lead\">Crie personagens, acompanhe sua ficha e consulte as regras da mesa.</p><p class=\"small muted\" data-account>Verificando conta…</p><span class=\"chip\" data-role></span> <button type=\"button\" class=\"btn ghost\" data-logout hidden>Sair</button></div><a class=\"btn primary\" href=\"#criar\">+ Criar personagem</a></section>\n<section><div class=\"panel-head\"><h2 data-list-title>Personagens</h2><span class=\"small muted\">Privacidade por conta</span></div><div class=\"grid grid-3\" data-characters></div></section>\n<section class=\"panel section-space\" id=\"criar\"><div class=\"panel-head\"><div><h2>Novo personagem</h2><p>Começa em branco: nenhuma ficha de outro jogador é copiada.</p></div></div><form class=\"form-grid\" data-create><label class=\"field\">Nome do personagem<input name=\"name\" required maxlength=\"160\" placeholder=\"Como seu herói se chama?\"></label><label class=\"field\">Nome do jogador<input name=\"player\" maxlength=\"160\"></label><label class=\"field\">Classe<input name=\"className\" placeholder=\"Bárbaro, guerreiro, mago…\" maxlength=\"120\"></label><label class=\"field\">Ancestralidade<input name=\"ancestry\" placeholder=\"Anão, elfo, humano…\" maxlength=\"120\"></label><div class=\"field full\"><button class=\"btn primary\">Criar minha ficha</button></div></form><button class=\"btn section-space\" data-recover-old hidden>Recuperar cópia da ficha antiga deste aparelho</button></section>\n<section class=\"panel section-space\" data-admin hidden><div class=\"panel-head\"><div><div class=\"eyebrow\">Administração da mesa</div><h2>Convites e papéis</h2><p>Ser administrador não dá acesso automático às fichas. Somente o papel Mestre vê todos.</p></div></div><div class=\"note\" data-invite-help>1. Cadastre o e-mail e o papel abaixo.<br>2. Libere esse mesmo e-mail na opção <strong>Compartilhar</strong> do Site no ChatGPT (ou peça aqui a liberação).<br>3. Envie o link ao convidado. Ele deve entrar com o e-mail cadastrado.<br><small>O cadastro da mesa não envia e-mail nem altera a lista privada do Site automaticamente.</small></div><form class=\"form-grid section-space\" data-invite><label class=\"field\">E-mail da conta do convidado<input type=\"email\" name=\"email\" required autocomplete=\"email\" placeholder=\"jogador@exemplo.com\"></label><label class=\"field\">Papel<select name=\"role\"><option value=\"player\">Jogador — vê e edita somente os próprios personagens</option><option value=\"master\">Mestre — consulta todos os personagens</option></select></label><div class=\"field full\"><button class=\"btn primary\">Cadastrar convite</button></div></form><p class=\"small\" role=\"status\" data-invite-result></p><div class=\"form-grid\"><label class=\"field\">Link para enviar<input readonly data-invite-link></label><button type=\"button\" class=\"btn\" data-copy-link>Copiar link</button></div><div class=\"divider\"></div><h3>Pessoas da mesa</h3><div class=\"grid section-space\" data-members></div></section>\n<section class=\"note section-space\">Jogador: só os próprios personagens. Mestre: consulta todas as fichas, sem editar as dos outros. As verificações acontecem no servidor, inclusive em links diretos.</section></main><footer class=\"shell footer\"><span>Mesa privada · só para convidados</span><span>Dados na nuvem · backup por personagem</span></footer><script src=\"app.js\"></script></body></html>\n","progressao.html":"<!doctype html><html lang=\"pt-BR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Progressão · Mesa Pathfinder</title><link rel=\"stylesheet\" href=\"styles.css\"></head><body><header class=\"topbar\"><div class=\"shell topbar-inner\"><a class=\"brand\" href=\"mesa.html\"><span class=\"brand-title\">Mesa Pathfinder</span></a><nav><a href=\"mesa.html\">Mesa</a></nav></div></header><main class=\"shell\"><section class=\"hero\"><div><div class=\"eyebrow\">Plano de evolução</div><h1>Progressão</h1><p class=\"cloud-status\" data-cloud-status>Carregando…</p></div><div class=\"hero-actions\"><button class=\"btn primary\" data-save>Salvar agora</button><button class=\"btn\" data-export>Baixar backup</button></div></section><section class=\"panel\"><h2>Escolhas atuais</h2><div class=\"form-grid section-space\"><label class=\"field\">Características de ancestralidade e herança<input data-bind=\"feats.ancestry\"></label><label class=\"field\">Talento de ancestralidade<input data-bind=\"feats.ancestryTalent\"></label><label class=\"field\">Talento de perícia da biografia<input data-bind=\"feats.background\"></label><label class=\"field\">Talento de classe — nível 1<input data-bind=\"feats.class1\"></label><label class=\"field\">Talento de classe — nível 2<input data-bind=\"feats.class2\"></label><label class=\"field\">Talento de perícia — nível 2<input data-bind=\"feats.skill2\"></label><label class=\"field\">Dedicação / arquétipo<input data-bind=\"feats.archetype\"></label></div></section><section class=\"panel section-space\"><h2>Do nível 1 ao 20</h2><p class=\"muted\">Planejamento livre; tipos de ganho variam conforme a classe e as regras da mesa.</p><div class=\"grid\" id=\"level-plans\"></div></section><div class=\"save-bar\"><button class=\"btn primary\" data-save>Salvar progressão <span data-save-status></span></button></div></main><script>document.getElementById('level-plans').innerHTML=Array.from({length:20},(_,i)=>`<details class=\"level-plan\"><summary>Nível ${i+1}</summary><div class=\"form-grid section-space\"><label>Classe / arquétipo<input data-save-key=\"level${i+1}-class\"></label><label>Perícia<input data-save-key=\"level${i+1}-skill\"></label><label class=\"field full\">Outros ganhos e observações<textarea data-save-key=\"level${i+1}-notes\"></textarea></label></div></details>`).join('');</script><script src=\"app.js\"></script></body></html>\n","regras.js":"// Regras do catálogo SRD: rótulos e montagem do detalhe de uma entrada (GET /api/entries/:id).\n// Compartilhado pela busca, pela página Sessão e pelo painel do grupo como window.Regras.\n(() => {\n  const TYPE_LABELS = { spell: 'Magia', focus: 'Magia de foco', ritual: 'Ritual', feat: 'Talento', class: 'Classe', ancestry: 'Ancestralidade', condition: 'Condição', item: 'Item' };\n  const BOOK_NAMES = { livro1: 'Livro 1', livro2: 'Livro 2' };\n  const escapeHtml = value => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;');\n  // o servidor marca os termos com \\x01/\\x02; escapamos o texto e transformamos as marcas em <mark>\n  const markify = value => escapeHtml(value).replace(/\\x01/g, '<mark>').replace(/\\x02/g, '</mark>');\n\n  function metaLine(entry) {\n    const parts = [TYPE_LABELS[entry.type] || entry.type];\n    if (entry.level != null) parts.push('nível ' + entry.level);\n    if (entry.category) parts.push(entry.category);\n    parts.push(`${BOOK_NAMES[entry.book] || entry.book}, p. ${entry.page}`);\n    return parts.join(' · ');\n  }\n\n  function fieldRow(label, value) {\n    if (!value) return '';\n    return `<div class=\"detail-field\"><span>${escapeHtml(label)}</span><div>${escapeHtml(value)}</div></div>`;\n  }\n\n  function bookLink(entry) {\n    return `<a class=\"btn\" href=\"livro.html?book=${encodeURIComponent(entry.book)}&page=${entry.page}\" target=\"_blank\" rel=\"noopener\">Ver no livro ↗</a>`;\n  }\n\n  // Corpo da regra, sem cabeçalho: campos do tipo, texto e elevações.\n  function bodyHtml(entry) {\n    const d = entry.data || {};\n    if (entry.type === 'spell' || entry.type === 'focus' || entry.type === 'ritual') {\n      return fieldRow('Tradições', d.traditions) + fieldRow('Domínio', d.domain) + fieldRow('Patrono', d.patron) +\n        fieldRow('Tempo de execução', d.time) + fieldRow('Distância', d.range) + fieldRow('Alvos', d.targets) +\n        fieldRow('Área', d.area) + fieldRow('Defesa', d.defense) + fieldRow('Duração', d.duration) + fieldRow('Custo', d.cost) +\n        fieldRow('Requerimentos', d.requirements) + fieldRow('Teste primário', d.primaryCheck) + fieldRow('Testes secundários', d.secondaryChecks) +\n        (d.text ? `<p class=\"detail-text\">${escapeHtml(d.text)}</p>` : '') +\n        (d.heightened?.length ? `<h4>Elevações</h4>` + d.heightened.map(h => `<p class=\"detail-text\"><strong>(+${h.plus})</strong> ${escapeHtml(h.text)}</p>`).join('') : '');\n    }\n    if (entry.type === 'feat') {\n      return fieldRow('Categoria', d.category || entry.category) + fieldRow('Pré-requisitos', d.prerequisites) +\n        fieldRow(d.actions === 'reaction' || d.actions === 'free-action' ? 'Acionamento' : 'Gatilho', d.trigger) +\n        (d.text ? `<p class=\"detail-text\">${escapeHtml(d.text)}</p>` : '');\n    }\n    if (entry.type === 'class') {\n      return fieldRow('PV por nível', d.hpPerLevel) + fieldRow('Atributo-chave', d.keyAttribute) +\n        (d.proficiencies ? `<h4>Proficiências iniciais</h4><pre class=\"detail-pre\">${escapeHtml(d.proficiencies)}</pre>` : '') +\n        (d.progression?.length ? `<h4>Progressão</h4><div class=\"table-wrap\"><table><thead><tr><th>Nível</th><th>Características de classe</th></tr></thead><tbody>` +\n          d.progression.map(row => `<tr><td class=\"level-cell\">${row.level}</td><td>${escapeHtml(row.features)}</td></tr>`).join('') + '</tbody></table></div>' : '');\n    }\n    if (entry.type === 'ancestry') {\n      return fieldRow('Pontos de vida', d.hp) + fieldRow('Tamanho', d.size) + fieldRow('Velocidade', d.speed) +\n        fieldRow('Melhorias de atributo', (d.boosts || []).join(', ')) + fieldRow('Defeitos de atributo', (d.flaws || []).join(', ')) +\n        fieldRow('Idiomas', d.languages) + fieldRow('Traços', (d.traits || []).join(', ')) +\n        (d.heritages?.length ? `<h4>Heranças</h4>` + d.heritages.map(h => `<p class=\"detail-text\"><strong>${escapeHtml(h.name)}</strong> ${escapeHtml(h.text)}</p>`).join('') : '');\n    }\n    return d.text ? `<p class=\"detail-text\">${escapeHtml(d.text)}</p>` : '';\n  }\n\n  // Detalhe completo: cabeçalho com \"Ver no livro\" (mais os botões de `actions`), traços e corpo.\n  function detailHtml(entry, { actions = '' } = {}) {\n    return `<div class=\"panel-head\"><div><div class=\"eyebrow\">${TYPE_LABELS[entry.type] || entry.type}${entry.level != null ? ' · nível ' + entry.level : ''}</div><h2>${escapeHtml(entry.name)}</h2><p class=\"small muted\">${escapeHtml(metaLine(entry))}</p></div><div class=\"detail-actions\">${bookLink(entry)}${actions}</div></div>\n  ${(entry.traits || []).length ? `<div class=\"chips\">${entry.traits.map(t => `<span class=\"chip\">${escapeHtml(t)}</span>`).join('')}</div>` : ''}${bodyHtml(entry)}`;\n  }\n\n  window.Regras = { TYPE_LABELS, BOOK_NAMES, escapeHtml, markify, metaLine, bookLink, bodyHtml, detailHtml };\n})();\n","styles.css":":root {\n  --ink: #f4efe5;\n  --muted: #b7b0a4;\n  --bg: #111315;\n  --panel: #1b1e20;\n  --panel-2: #24282a;\n  --line: #3a4041;\n  --gold: #e2ad52;\n  --gold-soft: #5d4726;\n  --red: #c95b48;\n  --green: #8fbf8b;\n  --blue: #83b4c8;\n  --shadow: 0 18px 55px rgba(0,0,0,.25);\n}\n\n* { box-sizing: border-box; }\nhtml { background: var(--bg); }\nbody {\n  margin: 0;\n  color: var(--ink);\n  background:\n    radial-gradient(circle at 80% -10%, rgba(226,173,82,.13), transparent 30rem),\n    linear-gradient(145deg, #111315 0%, #171a1b 100%);\n  font: 16px/1.5 Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n}\na { color: inherit; text-decoration: none; }\n[hidden] { display: none !important; }\nbutton:disabled, input:disabled, textarea:disabled, select:disabled { opacity: .65; cursor: default; }\na:focus-visible, button:focus-visible, summary:focus-visible { outline: 2px solid var(--gold); outline-offset: 3px; }\nbutton, input, textarea { font: inherit; }\nbutton { cursor: pointer; min-height: 42px; }\n.shell { width: min(1180px, calc(100% - 32px)); margin: 0 auto; }\n.topbar { border-bottom: 1px solid rgba(255,255,255,.09); background: rgba(17,19,21,.88); backdrop-filter: blur(18px); position: sticky; top: 0; z-index: 5; }\n.topbar-inner { min-height: 78px; display: flex; gap: 24px; align-items: center; justify-content: space-between; }\n.brand { display: flex; align-items: center; gap: 13px; }\n.brand-mark { width: 38px; height: 38px; border: 2px solid var(--gold); display: grid; place-items: center; color: var(--gold); font-weight: 900; transform: rotate(45deg); }\n.brand-mark span { transform: rotate(-45deg); }\n.brand-title { font-weight: 800; letter-spacing: .02em; }\n.brand-sub { color: var(--muted); font-size: .82rem; }\nnav { display: flex; gap: 6px; flex-wrap: wrap; }\nnav a { color: var(--muted); padding: 9px 12px; border-radius: 8px; font-size: .9rem; }\nnav a:hover, nav a.active { color: var(--ink); background: var(--panel-2); }\nmain { padding: 38px 0 70px; }\n.eyebrow { color: var(--gold); text-transform: uppercase; letter-spacing: .16em; font-size: .73rem; font-weight: 800; }\nh1, h2, h3 { margin: 0; line-height: 1.15; }\nh1 { margin-top: 8px; font-size: clamp(2rem, 4vw, 3.5rem); letter-spacing: -.04em; }\nh2 { font-size: 1.35rem; }\nh3 { font-size: 1rem; }\n.lead { color: var(--muted); max-width: 680px; margin: 12px 0 0; }\n.cloud-status { color: var(--muted); font-size: .8rem; margin: 8px 0 0; }\n.cloud-status[data-state=\"saved\"] { color: var(--green); }\n.cloud-status[data-state=\"saving\"] { color: var(--gold); }\n.cloud-status[data-state=\"offline\"] { color: var(--red); }\n.hero-name { background: transparent; border: 0; border-bottom: 1px solid var(--gold-soft); border-radius: 0; color: var(--ink); font-size: inherit; font-weight: 800; letter-spacing: -.04em; padding: 0; width: min(100%, 720px); }\n.hero .lead input { display: inline; width: auto; min-width: 4ch; background: transparent; border: 0; border-bottom: 1px dotted var(--line); border-radius: 0; padding: 0; color: var(--muted); }\n.file-button { display: inline-flex; align-items: center; position: relative; overflow: hidden; }\n.file-button input { position: absolute; inset: 0; opacity: 0; cursor: pointer; width: 100%; height: 100%; }\n.hero { display: flex; align-items: end; justify-content: space-between; gap: 24px; margin-bottom: 28px; }\n.hero-actions { display: flex; gap: 10px; flex-wrap: wrap; }\n.btn { border: 1px solid var(--line); color: var(--ink); background: var(--panel-2); border-radius: 8px; padding: 10px 14px; font-weight: 700; }\n.btn:hover { border-color: var(--gold); }\n.btn.primary { background: var(--gold); color: #1b160e; border-color: var(--gold); }\n.btn.ghost { background: transparent; }\n.grid { display: grid; gap: 16px; }\n.grid-4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }\n.grid-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }\n.grid-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n.panel { background: rgba(27,30,32,.92); border: 1px solid var(--line); border-radius: 14px; padding: 20px; box-shadow: var(--shadow); }\n.panel + .panel { margin-top: 16px; }\n.panel-head { display: flex; justify-content: space-between; align-items: center; gap: 12px; margin-bottom: 16px; }\n.panel-head p { margin: 0; color: var(--muted); font-size: .9rem; }\n.stat { padding: 17px; border: 1px solid var(--line); border-radius: 12px; background: linear-gradient(145deg, rgba(36,40,42,.9), rgba(27,30,32,.9)); }\n.stat-label { color: var(--muted); font-size: .78rem; text-transform: uppercase; letter-spacing: .1em; }\n.stat-value { font-size: 1.8rem; font-weight: 800; margin-top: 4px; }\n.stat-note { color: var(--muted); font-size: .82rem; }\n.accent { color: var(--gold); }\n.danger { color: var(--red); }\n.good { color: var(--green); }\n.info { color: var(--blue); }\n.form-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }\n.field { display: grid; gap: 6px; }\n.field.full { grid-column: 1 / -1; }\nlabel { color: var(--muted); font-size: .82rem; }\ninput, textarea, select { width: 100%; color: var(--ink); background: #121516; border: 1px solid var(--line); border-radius: 8px; padding: 10px 11px; outline: none; }\ninput:focus, textarea:focus, select:focus { border-color: var(--gold); box-shadow: 0 0 0 3px rgba(226,173,82,.12); }\ntextarea { min-height: 110px; resize: vertical; }\n.chips { display: flex; flex-wrap: wrap; gap: 8px; }\n.chip { display: inline-flex; align-items: center; gap: 7px; padding: 7px 10px; border: 1px solid var(--line); border-radius: 999px; color: var(--muted); background: #151819; font-size: .87rem; }\n.chip strong { color: var(--ink); }\n.section-space { margin-top: 16px; }\n.table-wrap { overflow-x: auto; }\ntable { width: 100%; border-collapse: collapse; min-width: 620px; }\nth, td { padding: 12px 10px; border-bottom: 1px solid var(--line); text-align: left; vertical-align: top; }\nth { color: var(--muted); font-size: .75rem; text-transform: uppercase; letter-spacing: .08em; }\ntd { color: var(--ink); }\ntd input { min-width: 110px; }\n.level-current { background: rgba(226,173,82,.1); }\n.level-current td:first-child { color: var(--gold); font-weight: 900; }\n.checklist { display: grid; gap: 10px; }\n.check { display: flex; gap: 10px; align-items: flex-start; color: var(--muted); }\n.check input { width: 18px; height: 18px; accent-color: var(--gold); margin-top: 3px; }\n.note { border-left: 3px solid var(--gold); background: rgba(226,173,82,.08); padding: 12px 14px; color: #e7dbc1; border-radius: 0 8px 8px 0; }\n.footer { color: var(--muted); font-size: .82rem; padding: 20px 0 40px; display: flex; justify-content: space-between; gap: 16px; }\n.save-bar { position: sticky; bottom: 16px; display: flex; justify-content: flex-end; pointer-events: none; z-index: 4; }\n.save-bar .btn { pointer-events: auto; box-shadow: 0 10px 30px rgba(0,0,0,.35); }\n.muted { color: var(--muted); }\n.small { font-size: .84rem; }\n.divider { height: 1px; background: var(--line); margin: 16px 0; }\n.section-kicker { color: var(--gold); font-size: .74rem; font-weight: 800; text-transform: uppercase; letter-spacing: .13em; margin-bottom: 8px; }\n.skill-list { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }\n.skill-card, .ability-card, .attack-card { border: 1px solid var(--line); border-radius: 10px; background: #151819; padding: 12px; }\n.skill-main { display: grid; grid-template-columns: 1fr 86px; align-items: center; gap: 10px; }\n.skill-main strong { display: block; }\n.skill-main small { display: block; color: var(--muted); font-size: .75rem; margin-top: 1px; }\n.skill-main input { text-align: center; font-weight: 800; color: var(--gold); }\ndetails { margin-top: 8px; color: var(--muted); font-size: .85rem; }\nsummary { color: var(--blue); cursor: pointer; font-weight: 700; }\ndetails p { margin: 7px 0 0; }\n.ability-title { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-bottom: 8px; }\n.ability-title input { font-weight: 800; color: var(--gold); }\n.ability-title span { flex: none; color: var(--muted); font-size: .76rem; }\n.ability-card textarea { min-height: 118px; }\n.info-button { border: 1px solid var(--line); background: transparent; color: var(--blue); border-radius: 999px; padding: 7px 10px; min-height: 36px; }\ndialog { width: min(520px, calc(100% - 24px)); border: 1px solid var(--line); border-radius: 14px; color: var(--ink); background: var(--panel); padding: 22px; box-shadow: var(--shadow); }\ndialog::backdrop { background: rgba(0,0,0,.68); }\ndialog form { display: flex; justify-content: flex-end; margin-top: 18px; }\n.two-col-mobile { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }\n.reference-controls { display: grid; grid-template-columns: minmax(125px,1fr) 100px auto; align-items: end; gap: 8px; margin: 12px 0; }\n.reference-controls label { display: grid; gap: 5px; }\n.reference-controls .btn { font-size: .78rem; white-space: nowrap; text-align: center; }\n.disabled-link { opacity: .4; pointer-events: none; }\n.character-card { display: grid; gap: 14px; padding: 24px; border: 1px solid var(--line); border-radius: 14px; background: linear-gradient(145deg, #292b2b, #191c1e); transition: border-color .15s, transform .15s; min-width: 0; }\n.character-card:hover { border-color: var(--gold); transform: translateY(-2px); }\n.character-card h3 { font-size: 1.6rem; overflow-wrap: anywhere; }\n.character-card p { color: var(--muted); margin: 0; }\n.character-card small { color: var(--muted); overflow-wrap: anywhere; }\n.card-arrow { color: var(--gold); font-weight: 700; }\n.member-row { display: grid; grid-template-columns: minmax(0,1fr) 130px auto; gap: 12px; align-items: center; padding: 14px; border: 1px solid var(--line); border-radius: 10px; }\n.member-row strong { overflow-wrap: anywhere; }\n.member-row small { display: block; color: var(--muted); margin-top: 5px; }\n.level-plan { padding: 14px; border: 1px solid var(--line); border-radius: 10px; }\n.book-shell { width: min(1050px, calc(100% - 24px)); }\n.book-title { font-size: 2rem; margin-bottom: 20px; }\n.book-toolbar { display: flex; gap: 10px; align-items: end; flex-wrap: wrap; }\n.book-toolbar label { display: grid; gap: 5px; }\n.book-toolbar input { max-width: 130px; }\n.book-image-wrap { margin: 20px 0; overflow: auto; border-radius: 12px; background: #35393b; }\n.book-image-wrap img { display: block; width: 100%; height: auto; }\n.book-image-wrap.zoomed img { width: 1500px; max-width: none; }\n.hero-name { max-width: 100%; }\n.hero > div { min-width: 0; }\n@media (max-width: 620px) { .reference-controls { grid-template-columns: minmax(0,1fr) 88px; } .reference-controls .btn { grid-column: 1 / -1; } .member-row { grid-template-columns: minmax(0,1fr) auto; } .member-row > div { grid-column: 1 / -1; } .hero-actions { width: 100%; } .hero-actions .btn { flex: 1 1 auto; text-align: center; } .book-toolbar button { flex: 1; } .character-card { padding: 20px; } }\n@media (max-width: 900px) { .grid-4 { grid-template-columns: repeat(2, minmax(0,1fr)); } .hero { align-items: flex-start; flex-direction: column; } }\n@media (max-width: 620px) { .shell { width: min(100% - 22px, 1180px); } .topbar-inner { align-items: flex-start; flex-direction: column; padding: 14px 0; gap: 12px; } nav { width: 100%; overflow-x: auto; flex-wrap: nowrap; } nav a { white-space: nowrap; } main { padding-top: 28px; } .grid-4, .grid-3, .grid-2, .form-grid, .skill-list { grid-template-columns: 1fr; } .two-col-mobile { grid-template-columns: 1fr; } .panel { padding: 16px; } .footer { flex-direction: column; } .ability-title { align-items: flex-start; flex-direction: column; } .skill-main { grid-template-columns: 1fr 72px; } input, textarea, select { font-size: 16px; } .search-layout { grid-template-columns: 1fr; } .search-filters { grid-template-columns: 1fr 1fr; } .search-box { flex-direction: column; align-items: stretch; } }\n\n/* --- Busca SRD --- */\n.search-box { display: flex; gap: 10px; margin-bottom: 14px; }\n.search-box input[type=\"search\"] { font-size: 1.05rem; padding: 13px 14px; }\n.search-filters { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; margin-bottom: 14px; }\n.search-filters label { display: grid; gap: 5px; }\n#stats { margin: 4px 0 12px; }\n#stats .chip { cursor: pointer; background: #151819; }\n#stats .chip:hover { border-color: var(--gold); color: var(--ink); }\n.search-layout { display: grid; grid-template-columns: minmax(0, 1fr) minmax(340px, 460px); gap: 16px; align-items: start; margin-top: 16px; }\n.result-card { border: 1px solid var(--line); border-radius: 12px; background: linear-gradient(145deg, #20232400, rgba(27,30,32,.9)); background-color: #17191b; padding: 14px 16px; margin-bottom: 10px; cursor: pointer; transition: border-color .12s; }\n.result-card:hover { border-color: var(--gold); }\n.result-card.selected { border-color: var(--gold); box-shadow: 0 0 0 1px var(--gold); }\n.result-card.page-result { cursor: pointer; background: #14171a; }\n.result-card h3 { font-size: 1.02rem; letter-spacing: -.01em; }\n.result-card .chip { padding: 4px 9px; font-size: .74rem; }\n.result-snippet { margin: 8px 0 0; color: var(--muted); }\n.result-snippet mark { background: rgba(226,173,82,.22); color: #f3ddab; border-radius: 3px; padding: 0 2px; }\n.detail-panel { position: sticky; top: 96px; max-height: calc(100vh - 120px); overflow-y: auto; }\n.detail-actions { display: flex; gap: 8px; flex-wrap: wrap; }\n.detail-field { display: grid; grid-template-columns: 130px 1fr; gap: 10px; padding: 7px 0; border-bottom: 1px solid rgba(255,255,255,.06); font-size: .92rem; }\n.detail-field > span { color: var(--muted); }\n.detail-text { white-space: pre-wrap; margin: 10px 0; line-height: 1.55; }\n.detail-pre { white-space: pre-wrap; background: #121516; border: 1px solid var(--line); border-radius: 8px; padding: 10px; font-size: .84rem; color: var(--muted); }\n.detail-panel h4 { margin: 16px 0 6px; color: var(--gold); font-size: .8rem; text-transform: uppercase; letter-spacing: .1em; }\n.detail-panel table { min-width: 0; }\n.level-cell { font-weight: 800; color: var(--gold); width: 44px; }\n#results h2 { margin: 4px 0 12px; }\n"};
